JS = r"""var WEEK=["日","一","二","三","四","五","六"];function pad(n){return String(n).padStart(2,"0")}function updateHero(){var d=new Date();document.getElementById("hero-date").textContent=d.getFullYear()+" 年 "+pad(d.getMonth()+1)+" 月 "+pad(d.getDate())+" 日 星期"+WEEK[d.getDay()];}updateHero();var CATS=["全部","图像-生图","图像-修图","调研","通用","需求"];var ICONS={"全部":"\uD83D\uDCC2","图像-生图":"\uD83C\uDFA8","图像-修图":"\u270F\uFE0F","调研":"\uD83D\uDD0D","通用":"\u26A1","需求":"\uD83D\uDCA1"};var all=[],cur="全部",q="",navC=false,demC=false,tt;function toast(msg,type,ms){ms=ms||2200;type=type||"";var el=document.getElementById("toast");el.textContent=msg;el.className="show"+(type?" toast-"+type:"");clearTimeout(tt);tt=setTimeout(function(){el.className="";},ms);}async function api(url,opts){opts=opts||{};var r=await fetch(url,opts);if(!r.ok)throw new Error(await r.text());return r.json();}function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");}document.getElementById("sidebarToggle").onclick=function(){navC=!navC;document.getElementById("navItems").classList.toggle("collapsed",navC);document.getElementById("stoggleLbl").textContent=navC?"\u25BC 展开":"\u25B2 收起";};document.getElementById("demandToggleBtn").onclick=function(){demC=!demC;document.getElementById("demandBody").classList.toggle("collapsed",demC);document.getElementById("demandToggleLabel").textContent=demC?"\u25BC 展开":"\u25B2 收起";};function renderNav(){var nav=document.getElementById("catNav");var cnt={};CATS.forEach(function(c){cnt[c]=0;});all.forEach(function(p){cnt["全部"]++;cnt[p.category]=(cnt[p.category]||0)+1;});nav.innerHTML="";CATS.forEach(function(cat){var b=document.createElement("button");b.className="nav-item"+(cur===cat?" active":"");b.innerHTML='<span class="ni">'+ICONS[cat]+'</span><span class="nl">'+esc(cat)+'</span><span class="nc">'+(cnt[cat]||0)+"</span>";b.onclick=function(){cur=cat;renderNav();render();renderStats();};nav.appendChild(b);});}function renderStats(){document.getElementById("hd-total").textContent=all.filter(function(p){return p.category!=="需求";}).length;document.getElementById("hd-likes").textContent=all.reduce(function(s,p){return s+p.likes;},0);document.getElementById("hd-demands").textContent=all.filter(function(p){return p.category==="需求";}).length;document.getElementById("tb-count").textContent=getF().length+" 条";}function getF(){return all.filter(function(p){if(cur!=="全部"&&p.category!==cur)return false;if(q){var l=q.toLowerCase();if(!p.title.toLowerCase().includes(l)&&!p.content.toLowerCase().includes(l))return false;}return true;});}function render(){var g=document.getElementById("promptGrid");var f=getF();document.getElementById("tb-count").textContent=f.length+" 条";if(!f.length){g.innerHTML='<div class="empty"><div class="empty-icon">\uD83D\uDD0D</div><p>没有匹配的提示词</p></div>';return;}g.innerHTML="";f.forEach(function(p){var c=document.createElement("div");c.className="card";var m={"图像-生图":"bg-h","图像-修图":"bg-x","调研":"bg-y","通用":"bg-t","需求":"bg-q"}[p.category]||"bg-t";c.innerHTML='<div class="c-top"><span class="badge '+m+'">'+esc(p.category)+'</span><span class="title" title="'+esc(p.title)+'">'+esc(p.title)+'</span></div><div class="content" id="pc-'+p.id+'">'+esc(p.content)+'</div><span class="expand" id="pe-'+p.id+'" onclick="te('+p.id+')">展开全文 \u25BC</span><div class="footer"><span class="date">'+p.created_at.slice(0,10)+'</span><button class="btn btn-copy" onclick="cp('+p.id+',this)">\uD83D\uDCCB 复制</button><button class="btn btn-like" onclick="lk('+p.id+',this)">\uD83D\uDC4D <span class="like-num">'+p.likes+'</span></button><button class="btn btn-del" onclick="dl('+p.id+')">\uD83D\uDDD1</button></div>';g.appendChild(c);requestAnimationFrame(function(){var el=document.getElementById("pc-"+p.id),ex=document.getElementById("pe-"+p.id);if(el&&ex&&el.scrollHeight<=el.clientHeight+2)ex.style.display="none";});});}function te(id){var el=document.getElementById("pc-"+id),ex=document.getElementById("pe-"+id);if(!el||!ex)return;var e=el.classList.toggle("expanded");ex.textContent=e?"\u6536\u8D77 \u25B2":"\u5C55\u5F00\u5168\u6587 \u25BC";}function cp(id,btn){var p=all.find(function(x){return x.id===id;});if(!p)return;var ok=function(){btn.textContent="\u2705 已复制";btn.classList.add("copied");toast("\u5DF2\u590D\u5236 \u2714","success");setTimeout(function(){btn.textContent="\uD83D\uDCCB 复制";btn.classList.remove("copied");},2000);};if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(p.content).then(ok).catch(function(){var t=document.createElement("textarea");t.value=p.content;t.style.cssText="position:fixed;top:-999px;left:-999px";document.body.appendChild(t);t.select();document.execCommand("copy");document.body.removeChild(t);ok();});}else{var t=document.createElement("textarea");t.value=p.content;t.style.cssText="position:fixed;top:-999px;left:-999px";document.body.appendChild(t);t.select();document.execCommand("copy");document.body.removeChild(t);ok();}}async function lk(id,btn){btn.disabled=true;try{var u=await api("/api/prompts/"+id+"/like",{method:"POST"});var i=all.findIndex(function(x){return x.id===id;});if(i>=0)all[i].likes=u.likes;btn.querySelector(".like-num").textContent=u.likes;btn.classList.add("liked");all.sort(function(a,b){return b.likes-a.likes||b.id-a.id;});renderNav();render();renderStats();if(u.category==="需求")renderDemands();toast("\uD83D\uDC4D 点赞成功！","success");}catch(e){toast("\u70B9\u8D5E\u5931\u8D25","error");}finally{btn.disabled=false;}}async function dl(id){if(!confirm("\u786E\u5B9A\u5220\u9664\uFF1F"))return;try{await api("/api/prompts/"+id,{method:"DELETE"});all=all.filter(function(p){return p.id!==id;});renderNav();render();renderStats();toast("\u5DF2\u5220\u9664");}catch(e){toast("\u5220\u9664\u5931\u8D25","error");}}async function renderDemands(){var row=document.getElementById("demandRow"),bad=document.getElementById("demandBadge");try{var d=await api("/api/demands");bad.textContent=d.length+" 条";if(!d.length){row.innerHTML='<div class="loading" style="color:var(--sub)">暂无需求，快来第一个提！</div>';return;}row.innerHTML="";d.forEach(function(x,i){var c=document.createElement("div");c.className="demand-card";c.innerHTML='<div class="demand-rr"><span class="rank'+(i<3?" top3":"")+'">'+(i+1)+'</span><span class="rank-title" title="'+esc(x.title)+'">'+esc(x.title)+'</span></div><div class="rank-c">'+esc(x.content)+'</div><div class="rank-l">\uD83D\uDC4D '+x.likes+' 票</div>';row.appendChild(c);});}catch(e){row.innerHTML='<div class="loading">需求加载失败</div>';}}document.getElementById("addPromptForm").onsubmit=async function(e){e.preventDefault();var ti=document.getElementById("fp-title").value.trim(),co=document.getElementById("fp-content").value.trim(),ca=document.getElementById("fp-cat").value;if(!ti||!co){toast("\u6807\u9898\u548C\u5185\u5BB9\u4E0D\u80FD\u4E3A\u7A7A","error");return;}var btn=document.getElementById("btnSubmitPrompt");btn.disabled=true;btn.textContent="提交中...";try{var fd=new FormData();fd.append("title",ti);fd.append("content",co);fd.append("category",ca);var np=await api("/api/prompts",{method:"POST",body:fd});all.unshift(np);all.sort(function(a,b){return b.likes-a.likes||b.id-a.id;});document.getElementById("fp-title").value="";document.getElementById("fp-content").value="";renderNav();render();renderStats();toast("\u2705 提示词已添加！","success");}catch(err){toast("\u63D0\u4EA4\u5931\u8D25: "+err.message,"error");}finally{btn.disabled=false;btn.textContent="提交";}};};document.getElementById("addDemandForm").onsubmit=async function(e){e.preventDefault();var ti=document.getElementById("fd-title").value.trim(),co=document.getElementById("fd-content").value.trim();if(!ti||!co){toast("\u9700\u6C42\u6807\u9898\u548C\u5185\u5BB9\u4E0D\u80FD\u4E3A\u7A7A","error");return;}var btn=document.getElementById("btnSubmitDemand");btn.disabled=true;btn.textContent="提交中...";try{var fd=new FormData();fd.append("title",ti);fd.append("content",co);fd.append("category","需求");var np=await api("/api/prompts",{method:"POST",body:fd});all.unshift(np);all.sort(function(a,b){return b.likes-a.likes||b.id-a.id;});document.getElementById("fd-title").value="";document.getElementById("fd-content").value="";renderNav();render();renderStats();renderDemands();toast("\uD83D\uDCA1 需求已提交！","success");}catch(err){toast("\u63D0\u4EA4\u5931\u8D25: "+err.message,"error");}finally{btn.disabled=false;btn.textContent="提交需求";}};};document.getElementById("searchInput").oninput=function(e){q=e.target.value.trim();render();renderStats();};async function init(){try{all=await api("/api/prompts");all.sort(function(a,b){return b.likes-a.likes||b.id-a.id;});renderNav();render();renderStats();renderDemands();}catch(e){document.getElementById("promptGrid").innerHTML='<div class="empty"><div class="empty-icon">\u26A0\uFE0F</div><p>数据加载失败，请刷新</p></div>';}}init();"""

